Tentatively I wrote the following to get the difference type names. Still looking into how to get it into the Write function naturally.

```
        private void ResolveTypeNameDifference(object expected, object actual, out string expectedType, out string actualType) {
            string[] expectedOriginalType = expected.GetType().ToString().Split('.'); //Input expected : NUnit.Framework.Constraints.Outer.Middle.Inner.Class1
            string[] actualOriginalType = actual.GetType().ToString().Split('.'); //Input actual : NUnit.Framework.Constraints.Outer.Hey.Inner.Class1
            int actualStart = 0, expectStart = 0;
            for (int expectLen = expectedOriginalType.Length - 1,actualLen = actualOriginalType.Length - 1;
                expectLen >= 0 && actualLen >= 0;
                expectLen--, actualLen--) {
                if (expectedOriginalType[expectLen] != actualOriginalType[actualLen]) {
                    actualStart = actualLen;
                    expectStart = expectLen;
                    break;
                }
            }
            expectedType = String.Join(".", expectedOriginalType, expectStart, expectedOriginalType.Length- expectStart); //Output expectedType : Middle.Inner.Class1
            actualType = String.Join(".", actualOriginalType, actualStart, actualOriginalType.Length- actualStart); //Output actualType : Hey.Inner.Class1
        }
